/* Role dashboards (Figma 1780:77960): Business Manager, Clinician, Patient. Super Admin gets a holding page for now. */
(function () {
  const { esc, acts, chs } = App;
  const D = App.dash = {
    range: 'This Week', rev: 'This Month',
    week: { labels: ['12 Oct', '13 Oct', '14 Oct', '15 Oct', '16 Oct', '17 Oct', '18 Oct'], data: [24, 30, 27, 32, 22, 29, 49] },
    month: { labels: ['Week 1', 'Week 2', 'Week 3', 'Week 4', 'Week 5'], data: [118, 131, 124, 142, 136] },
    requests: [['18/10/2026', 'Ahmad Khan', 'Active Treatment', 'GLP-1 Intake', 'Website'], ['18/10/2026', 'Ahmad Khan', 'Under Review', 'GLP-1 Intake', 'Platform'], ['17/10/2026', 'Sarah Ali', 'Pending registration', 'GLP-1 Intake', 'Platform'], ['16/10/2026', 'Emma Brown', 'Completed', 'Blood test', 'Website'], ['15/10/2026', 'Daniel Reeves', 'More info required', 'Eligibility Check', 'Website'], ['15/10/2026', 'Priya Anand', 'Rejected', 'GLP-1 Intake', 'Website'], ['14/10/2026', 'Tom Bennett', 'Active Treatment', 'TRT review', 'Phone']],
    appts: { clinician: [{ id: 'a1', mon: 'Oct', day: 22, dow: 'Thu', time: '10:30 AM', dur: 15, title: 'Follow-up Consultation', who: 'Ahmed Raza', sub: 'GLP-1 review', mode: 'Online Appointment', kind: 'Follow-up' }, { id: 'a2', mon: 'Oct', day: 22, dow: 'Thu', time: '11:00 AM', dur: 30, title: 'Initial Assessment', who: 'Sarah Ali', sub: 'Weight management', mode: 'Face to face', kind: 'Initial Assessment' }],
      patient: [{ id: 'p1', mon: 'Oct', day: 22, dow: 'Thu', time: '10:30 AM', dur: 15, title: 'Follow-up Consultation', who: 'Dr Simon Hart', sub: 'Cardiologist', mode: 'Online Appointment', kind: 'Follow-up' }, { id: 'p2', mon: 'Nov', day: 3, dow: 'Tue', time: '09:15 AM', dur: 30, title: 'ECG Review', who: 'Dr Amelia Patel', sub: 'Cardiologist', mode: 'Face to face', kind: 'Initial Assessment' }] },
    cancelled: 2
  };
  const STATUS = { 'Active Treatment': ['t-green', 'ri-checkbox-circle-line'], Completed: ['t-green', 'ri-checkbox-circle-line'], 'Appointment Pending': ['t-green', 'ri-checkbox-circle-line'], 'Under Review': ['t-orange', 'ri-time-line'], 'Under Clinical Review': ['t-orange', 'ri-time-line'], 'Pending registration': ['t-orange', 'ri-time-line'], Pending: ['t-orange', 'ri-time-line'], 'More info required': ['t-blue', 'ri-information-line'], Rejected: ['t-red', 'ri-close-line'], Closed: ['t-red', 'ri-error-warning-line'] };
  const chip = s => { const [t, i] = STATUS[s] || ['t-grey', 'ri-information-line']; return `<span class="chip sm filled ${t}"><i class="${i}"></i>${esc(s)}</span>`; };
  const stat = ([label, value, foot, icon], feature) => `<div class="stat dstat ${feature ? 'feature' : ''}"><span class="dic"><i class="${icon}"></i></span><div class="stack"><span class="caption ${feature ? 'on-teal' : ''}">${label}</span><span class="dnum">${value}</span><span class="foot">${foot}</span></div></div>`;
  const head = (title, sub) => `<div class="stack g4"><h1 class="h5" style="font-weight:600">${title}</h1><p class="body2 muted" style="margin:0">${sub}</p></div>`;
  const quick = list => `<section class="card card-pad stack g12"><h2 class="dh2">Quick actions</h2>${list.map(([i, t, go]) => `<button class="qa" data-act="dash-go" data-go2="${go}"><span class="qa-ic"><i class="${i}"></i></span><span class="grow">${t}</span><i class="ri-arrow-right-s-line"></i></button>`).join('')}</section>`;
  const activity = () => `<section class="card card-pad stack g12"><div class="row between"><h2 class="dh2">Recent activity</h2><a href="#" class="link" data-act="soon" data-what="Activity history">View all</a></div><ul class="act-list">${[['ECG result added to Documents', '18 Oct · 11:48', true], ['Payment received · £469.99', '17 Oct · 09:12'], ['Report signed by Dr Amelia Patel', '16 Oct · 14:52'], ['Blood-pressure reading requested', '16 Oct · 15:02', true], ['Assessment submitted', '16 Oct · 13:44']].map(([t, d, hot]) => `<li class="${hot ? 'hot' : ''}"><span>${t}</span><small>${d}</small></li>`).join('')}</ul></section>`;
  acts['dash-go'] = el => { const go = el.dataset.go2; const key = go.startsWith('#/soon/') ? 'soon:' + go.slice(7) : null; if (key && !App.allowed(key)) { App.snack('That’s coming soon for your role.', 'info'); return; } App.go(go); };

  App.route('/dashboard', () => ({ bm, clinician, patient, admin, vadmin: bm }[App.role] || bm)(), { key: 'dashboard', icon: 'ri-dashboard-line', title: 'Dashboard' });

  /* ---------- Business Manager ---------- */
  function bm() { const me = App.me(); const set = D.range === 'This Week' ? D.week : D.month;
    return `${head(`Welcome back, ${esc(me.name)}`, 'Here’s what’s happening at your business today.')}
    <div class="stats dstats5">${[['Total Appointments', '142', '+12% from last week', 'ri-calendar-line'], ['Total Patients', '28', '+8% from last week', 'ri-user-line'], ['Total Staff', '28', '+8% from last week', 'ri-team-line'], ['Active Services', '18', '+2 from last week', 'ri-service-line'], ['Revenue', '£42,350', '+23% from last week', 'ri-money-pound-circle-line']].map((s, i) => stat(s, i === 0)).join('')}</div>
    <div class="dgrid3"><div class="stack g16" style="min-width:0">
      <section class="card card-pad stack g16"><div class="row between wrap g12"><h2 class="dh2 row g8">Appointments Overview <i class="ri-information-line muted" title="Booked appointments across all clinicians"></i></h2><div style="width:180px">${App.select('Sort', 'dash-range', ['This Week', 'This Month'], D.range, { cls: 'sm' })}</div></div>${lineChart(set)}</section>
      <div class="dgrid"><section class="card card-pad stack g12" style="min-width:0"><div class="row between"><h2 class="dh2">Requests List</h2><a href="#" class="link" data-act="soon" data-what="Requests">View All</a></div>
          <div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Request Date</th><th>Patient Name</th><th>Status</th><th style="text-align:right">Actions</th></tr></thead><tbody>${D.requests.slice(0, 5).map((r, i) => `<tr class="${i === 1 ? 'flagged' : ''}"><td>${i === 1 ? '<i class="ri-error-warning-line brand" title="Needs attention"></i> ' : ''}${r[0]}</td><td>${esc(r[1])}</td><td>${chip(r[2])}</td><td style="text-align:right"><button class="icon-btn s20" data-act="req-view" data-i="${i}" aria-label="View request from ${esc(r[1])}"><i class="ri-eye-line"></i></button></td></tr>`).join('')}</tbody></table></div></div></section>
        <section class="card card-pad stack g12" style="min-width:0"><div class="row between wrap g12"><h2 class="dh2">Revenue Summary</h2><div style="width:170px">${App.select('Sort', 'dash-rev', ['This Week', 'This Month'], D.rev, { cls: 'sm' })}</div></div>${revenue()}</section></div></div>
      <div class="stack g16" style="min-width:0">
        <section class="card card-pad stack g12"><div class="row between"><h2 class="dh2 row g8">Medical alerts <span class="chip sm solid t-red">3 new</span></h2><a href="#" class="link" data-act="dash-go" data-go2="#/soon/patients">View all</a></div>
          <div class="alert-card red"><div class="row between"><b class="row g8"><i class="ri-error-warning-line"></i>Ahmad Khan <span class="tag-red">High risk</span></b><small>2h ago</small></div><span>Aggressive behaviour towards staff. Do not see alone.</span></div>
          <div class="alert-card orange"><div class="row between"><b class="row g8"><i class="ri-heart-pulse-line"></i>Sarah Ali <span class="tag-orange">Alert</span></b><small>Yesterday</small></div><span>Penicillin allergy · from medical history</span></div></section>
        ${quick([['ri-add-line', 'New Appointment', '#/soon/appointments'], ['ri-user-add-line', 'Add New Patient', '#/soon/patients'], ['ri-pencil-line', 'Invite New Staff', '#/soon/staff-management'], ['ri-chat-new-line', 'Create New Service', '#/soon/appointments']])}
        <section class="card card-pad stack g12"><div class="row between"><h2 class="dh2">Staff Summary</h2><a href="#" class="link" data-act="dash-go" data-go2="#/soon/rota-management">View ROTA</a></div>
          ${[['Neil Sims', 'Clinician', 8, 'Fully Booked', 't-green'], ['Bonnie Green', 'Clinician', 6, 'Busy', 't-red'], ['Micheal Gough', 'Clinician', 5, 'Moderate', 't-orange'], ['Thomas Lean', 'Nurse', 2, 'Available', 't-green'], ['Lana Byrd', 'Nurse', 0, 'Off Today', 't-grey']].map(([n, r, s, st, t]) => `<div class="staff-row"><span class="cell2"><span>${n}</span><small>${r}</small></span><span class="stack g4"><small class="caption">${s}/8 Slots</small>${App.H ? App.H.prog(s, 8) : ''}</span>${App.chip(st, t, 'sm filled')}</div>`).join('')}
          <div class="staff-total"><b>Total Staff: 5</b><b class="brand">Total Appointments: 21/40</b></div></section></div></div>`; }
  function lineChart({ labels, data }) {
    const W = 1000, H = 220, L = 0, B = 2, max = Math.ceil(Math.max(...data) * 1.2 / 20) * 20, step = W / (data.length - 1);
    const pts = data.map((v, i) => [L + i * step, (H - B) - v / max * (H - B - 10)]);
    const d = pts.map((p, i) => { if (!i) return `M${p[0]},${p[1]}`; const p0 = pts[i - 2] || pts[i - 1], p1 = pts[i - 1], p3 = pts[i + 1] || p; const c1 = [p1[0] + (p[0] - p0[0]) / 6, p1[1] + (p[1] - p0[1]) / 6], c2 = [p[0] - (p3[0] - p1[0]) / 6, p[1] - (p3[1] - p1[1]) / 6]; return `C${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${p[0]},${p[1]}`; }).join(' ');
    const ticks = [0, 1, 2, 3, 4].map(k => max / 4 * k);
    App.after(() => { const svg = App.$('#lchart'); if (!svg) return; const tip = App.$('#ltip'), dot = App.$('#ldot'), vline = App.$('#lvline');
      const show = i => { const [x, y] = pts[i]; const r = svg.getBoundingClientRect(), s = r.width / W, sy = r.height / H; dot.setAttribute('cx', x); dot.setAttribute('cy', y); vline.setAttribute('x1', x); vline.setAttribute('x2', x); dot.style.opacity = vline.style.opacity = 1;
        tip.innerHTML = `<b>${labels[i]}${labels[i].startsWith('Week') ? ' · Oct' : ''}, 2026</b><span><i></i>Appointments: <b>${data[i]}</b></span>`; tip.hidden = false; tip.style.left = (x * s) + 'px'; tip.style.top = (y * sy) + 'px'; dot.setAttribute('transform', `translate(${x} ${y}) scale(${1 / s} ${1 / sy}) translate(${-x} ${-y})`); };
      svg.addEventListener('mousemove', e => { const r = svg.getBoundingClientRect(); const x = (e.clientX - r.left) * W / r.width; show(Math.max(0, Math.min(data.length - 1, Math.round((x - L) / step)))); });
      svg.addEventListener('mouseleave', () => { tip.hidden = true; dot.style.opacity = vline.style.opacity = 0; });
      svg.addEventListener('focus', () => show(data.length - 1)); svg.addEventListener('blur', () => { tip.hidden = true; });
      svg.addEventListener('keydown', e => { if (!['ArrowLeft', 'ArrowRight'].includes(e.key)) return; e.preventDefault(); const cur = labels.indexOf((tip.querySelector('b')?.textContent || '').replace(', 2026', '').replace(' · Oct', '')); show(Math.max(0, Math.min(data.length - 1, (cur < 0 ? data.length - 1 : cur) + (e.key === 'ArrowRight' ? 1 : -1)))); }); });
    return `<div class="lchart"><div class="ly">${ticks.slice().reverse().map(t => `<span>${t}</span>`).join('')}</div><div class="lplot"><div class="lchart-wrap"><svg id="lchart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" tabindex="0" aria-label="Appointments ${D.range.toLowerCase()}: ${labels.map((l, i) => `${l} ${data[i]}`).join(', ')}">
      ${ticks.map(t => { const y = (H - B) - t / max * (H - B - 10); return `<line x1="0" x2="${W}" y1="${y}" y2="${y}" class="grid" vector-effect="non-scaling-stroke"/>`; }).join('')}
      <line id="lvline" y1="10" y2="${H - B}" class="vline" vector-effect="non-scaling-stroke" style="opacity:0"/><path d="${d} L${pts[pts.length - 1][0]},${H - B} L${L},${H - B} Z" class="area"/><path d="${d}" class="line" vector-effect="non-scaling-stroke"/><circle id="ldot" r="5" class="dot" vector-effect="non-scaling-stroke" style="opacity:0"/></svg><div id="ltip" class="ltip" hidden></div></div><div class="lx">${labels.map(l => `<span>${l}</span>`).join('')}</div></div></div>`; }
  function revenue() { const wk = D.rev === 'This Week'; const total = wk ? '£9,840' : '£42,350'; const parts = [['Online Appointments', 35, '#2C7A7B'], ['Call Appointments', 20, '#0288D1'], ['Face to Face Appointments', 45, '#9C27B0']];
    let a = 0; const stops = parts.map(p => { const s = a; a += p[1]; return `${p[2]} ${s}% ${a}%`; }).join(',');
    return `<div class="rev-box"><div class="rev-top"><div class="cell2"><b style="font-weight:600;font-size:16px">Total Revenue</b><small>vs last ${wk ? 'week' : 'month'}</small></div><b class="rev-num">${total}</b></div>
      <div class="rev-body"><div class="donut sm" style="background:conic-gradient(${stops})" role="img" aria-label="Online 35%, call 20%, face to face 45%"><span></span></div><ul class="legend-list">${parts.map(p => `<li><i style="background:${p[2]}"></i>${p[0]}<b>${p[1]}%</b><span></span></li>`).join('')}</ul></div></div>`; }
  chs['dash-range'] = el => { D.range = el.value; App.render(); }; chs['dash-rev'] = el => { D.rev = el.value; App.render(); };
  acts['req-view'] = el => { const r = D.requests[+el.dataset.i];
    App.dialog(`${App.dlgHead(`Request from ${esc(r[1])}`, `${esc(r[3])} · received ${r[0]}`)}<div class="dlg-body"><div class="kv"><div><span>Patient</span><b>${esc(r[1])}</b></div><div><span>Request type</span><b>${esc(r[3])}</b></div><div><span>Source</span><b>${esc(r[4])}</b></div><div><span>Status</span><b>${chip(r[2])}</b></div></div></div><div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Close</button><button class="btn primary lg" data-act="req-open">Open request</button></div>`, { width: 480 }); };
  acts['req-open'] = () => { App.closeModal(); App.snack('Request details are coming soon.', 'info'); };

  /* ---------- appointments (clinician + patient) ---------- */
  const apptCards = role => { const list = D.appts[role];
    if (!list.length) return `<div class="empty" style="padding:32px 16px"><span class="ic"><i class="ri-calendar-line"></i></span><p>No upcoming appointments.</p></div>`;
    return list.map(a => `<article class="appt"><div class="appt-date"><span class="dbox"><small>${a.mon}</small><b>${a.day}</b><small>${a.dow}</small></span><span class="cell2" style="align-items:center"><span>${a.time}</span><small>${a.dur} minutes</small></span></div>
      <div class="grow stack g8"><div class="row between wrap g8"><b class="appt-t">${esc(a.title)}</b><span class="row g8">${App.chip('Confirmed', 't-green', 'sm')}${App.chip('Upcoming', 't-orange', 'sm')}</span></div>
        <span class="muted">${esc(a.who)} <span class="sep">•</span> ${esc(a.sub)}</span><span class="row g8 wrap caption" style="color:var(--text-2)"><i class="${a.mode === 'Online Appointment' ? 'ri-video-on-line' : 'ri-map-pin-line'} brand"></i>${a.mode} <span class="sep">•</span> <i class="ri-file-list-2-line brand"></i>${a.kind}</span>
        <div class="row g12 wrap">${a.mode === 'Online Appointment' ? `<button class="btn primary" data-act="appt-join"><i class="ri-video-on-line"></i>Join Appointment</button>` : ''}<button class="btn outlined" data-act="appt-resched" data-r="${role}" data-id="${a.id}"><i class="ri-calendar-line"></i>Reschedule</button><button class="btn text" style="color:var(--error)" data-act="appt-cancel" data-r="${role}" data-id="${a.id}">Cancel Appointment</button></div></div></article>`).join(''); };
  acts['appt-join'] = () => App.snack('Opening the video call in a new tab…', 'info');
  acts['appt-cancel'] = el => { const a = D.appts[el.dataset.r].find(x => x.id === el.dataset.id);
    App.dialog(`${App.dlgHead('Cancel this appointment?', `${esc(a.title)} · ${a.dow} ${a.day} ${a.mon}, ${a.time}`, 'ri-calendar-close-line')}<div class="dlg-body"><p class="body2 muted" style="margin:0">${el.dataset.r === 'patient' ? 'If you cancel more than 24 hours before, you’ll get a full refund.' : `${esc(a.who)} will be told by email and SMS.`}</p></div><div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Keep appointment</button><button class="btn danger lg" data-act="appt-cancel-go" data-r="${el.dataset.r}" data-id="${a.id}">Cancel appointment</button></div>`, { width: 460 }); };
  acts['appt-cancel-go'] = el => { const list = D.appts[el.dataset.r]; const i = list.findIndex(x => x.id === el.dataset.id); const [a] = list.splice(i, 1); D.cancelled++; App.closeModal(); App.render();
    App.snack(`${a.title} cancelled.`, 'success', { label: 'Undo', fn: () => { list.splice(i, 0, a); D.cancelled--; App.render(); } }); };
  let rs = null;
  acts['appt-resched'] = el => { rs = { r: el.dataset.r, id: el.dataset.id, day: 0, time: '' }; drawRs(); };
  const DAYS = [['Fri', 23, 'Oct'], ['Mon', 26, 'Oct'], ['Tue', 27, 'Oct'], ['Wed', 28, 'Oct'], ['Thu', 29, 'Oct']];
  function drawRs() { const a = D.appts[rs.r].find(x => x.id === rs.id);
    App.dialog(`${App.dlgHead('Reschedule appointment', `${esc(a.title)} with ${esc(a.who)}`)}<div class="dlg-body"><span class="sub2">Pick a day</span><div class="row g8 wrap">${DAYS.map((d, i) => `<button class="daychip ${rs.day === i ? 'on' : ''}" data-act="rs-day" data-i="${i}" aria-pressed="${rs.day === i}">${d[0]} ${d[1]}</button>`).join('')}</div>
      <span class="sub2">Pick a time</span><div class="row g8 wrap">${['09:00 AM', '10:30 AM', '11:15 AM', '02:00 PM', '03:30 PM'].map((t, i) => (i + rs.day) % 4 === 3 ? '' : `<button class="slot ${rs.time === t ? 'on' : ''}" data-act="rs-time" data-v="${t}" aria-pressed="${rs.time === t}">${t}</button>`).join('')}</div></div>
      <div class="dlg-foot"><button class="btn outlined lg" data-act="close-modal">Cancel</button><button class="btn primary lg" data-act="rs-go" ${rs.time ? '' : 'disabled'}>Confirm new time</button></div>`, { width: 520 }); }
  acts['rs-day'] = el => { rs.day = +el.dataset.i; rs.time = ''; drawRs(); }; acts['rs-time'] = el => { rs.time = el.dataset.v; drawRs(); };
  acts['rs-go'] = () => { const a = D.appts[rs.r].find(x => x.id === rs.id); const d = DAYS[rs.day]; Object.assign(a, { dow: d[0], day: d[1], mon: d[2], time: rs.time }); App.closeModal(); App.render(); App.snack(`Moved to ${d[0]} ${d[1]} ${d[2]}, ${rs.time}.`); };
  const reqTable = (rows, cols) => { const pg = App.dash.page || 0; const per = 5; const slice = rows.slice(pg * per, pg * per + per);
    return `<div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr>${cols.map(c => `<th>${c}</th>`).join('')}<th style="text-align:right">Actions</th></tr></thead><tbody>${slice.map(r => `<tr>${r.cells.map(c => `<td>${c}</td>`).join('')}<td style="text-align:right"><button class="icon-btn s20" data-act="req-view" data-i="${r.i}" aria-label="View request"><i class="ri-eye-line"></i></button></td></tr>`).join('')}</tbody></table></div>
      <div class="pager"><span>Rows per page: ${per}</span><span class="tnum">${pg * per + 1}–${Math.min(rows.length, pg * per + per)} of ${rows.length}</span><span class="row g4"><button class="icon-btn s20" data-act="rq-pg" data-d="-1" ${pg ? '' : 'disabled'} aria-label="Previous page"><i class="ri-arrow-left-s-line"></i></button><button class="icon-btn s20" data-act="rq-pg" data-d="1" ${(pg + 1) * per < rows.length ? '' : 'disabled'} aria-label="Next page"><i class="ri-arrow-right-s-line"></i></button></span></div></div>`; };
  acts['rq-pg'] = el => { App.dash.page = (App.dash.page || 0) + +el.dataset.d; App.render(); };

  /* ---------- Clinician ---------- */
  function clinician() { const me = App.me();
    return `${head(`Welcome back, ${esc(me.name)}`, 'Here’s what’s happening in your clinics today.')}
    <div class="stats dstats3">${[['Total Appointments', '142', '+12% from last week', 'ri-calendar-line'], ['New Requests', '28', '+8% from last week', 'ri-user-line'], ['Active Services', '18', '+2 from last week', 'ri-team-line']].map((s, i) => stat(s, i === 0)).join('')}</div>
    <div class="dgrid3"><div class="stack g16" style="min-width:0"><section class="card card-pad stack g16"><div class="row between"><h2 class="dh2">Upcoming appointments</h2><a href="#" class="link" data-act="dash-go" data-go2="#/soon/appointments">View All</a></div>${apptCards('clinician')}</section>
      <section class="card card-pad stack g16"><div class="row between"><h2 class="dh2">Your Requests</h2><a href="#" class="link" data-act="soon" data-what="Requests">View All</a></div>${reqTable(D.requests.map((r, i) => ({ i, cells: [r[0], esc(r[1]), chip(r[2]), esc(r[3]), esc(r[4])] })), ['Request Date', 'Patient Name', 'Status', 'Request Type', 'Source'])}</section></div>
      <div class="stack g16">${quick([['ri-calendar-line', 'My Appointments', '#/soon/appointments'], ['ri-calendar-schedule-line', 'ROTA', '#/soon/rota-management'], ['ri-contacts-line', 'My Profile', '#/soon/my-profile'], ['ri-add-line', 'Apply for Leave', '#/soon/leaves-management']])}${activity()}</div></div>`; }

  /* ---------- Patient ---------- */
  function patient() { const me = App.me(); const next = D.appts.patient[0];
    const rows = [['15/10/2026, 11:00 am', 'Eligibility Check', 'Under Clinical Review'], ['14/10/2026, 09:20 am', 'Eligibility Check', 'Appointment Pending'], ['02/10/2026, 04:10 pm', 'Request Review', 'Closed'], ['28/09/2026, 10:05 am', 'Request Review', 'Pending']];
    return `${head(`Welcome back, ${esc(me.first)}`, 'Here’s everything about your heart care in one place.')}
    <div class="stats dstats4">${[['Upcoming appointments', String(D.appts.patient.length), next ? `Next: ${next.dow} ${next.day} ${next.mon}, ${next.time.replace(' AM', '').replace(' PM', '')}` : 'Nothing booked', 'ri-time-line'], ['Total visits', '12', 'Since January 2026', 'ri-calendar-line'], ['Total Spent', '£240', 'On care this year', 'ri-money-pound-circle-line'], ['Cancelled Appointments', String(D.cancelled), `£${(D.cancelled * 47.5).toFixed(2)} refunded`, 'ri-close-circle-line']].map((s, i) => stat(s, i === 0)).join('')}</div>
    <div class="dgrid3"><div class="stack g16" style="min-width:0"><section class="card card-pad stack g16"><div class="row between"><h2 class="dh2">Upcoming appointments</h2><a href="#" class="link" data-act="dash-go" data-go2="#/soon/appointment">View All</a></div>${apptCards('patient')}</section>
      <section class="card card-pad stack g16"><div class="row between"><h2 class="dh2">Your Requests</h2><a href="#" class="link" data-act="dash-go" data-go2="#/soon/my-requests">View All</a></div>
        <div class="table-card"><div class="table-scroll"><table class="dt"><thead><tr><th>Request Date &amp; Time</th><th>Request</th><th>Status</th><th style="text-align:right">Actions</th></tr></thead><tbody>${rows.map(r => `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${chip(r[2])}</td><td style="text-align:right"><button class="icon-btn s20" data-act="pt-req" data-t="${esc(r[1])}" data-s="${esc(r[2])}" aria-label="View ${esc(r[1])}"><i class="ri-eye-line"></i></button></td></tr>`).join('')}</tbody></table></div></div></section></div>
      <div class="stack g16">${quick([['ri-add-line', 'Book New Appointment', '#/soon/appointment'], ['ri-calendar-line', 'My Appointments', '#/soon/appointment'], ['ri-user-line', 'My Profile', '#/soon/my-profile']])}${activity()}</div></div>`; }
  acts['pt-req'] = el => App.dialog(`${App.dlgHead(esc(el.dataset.t), 'Your request')}<div class="dlg-body"><div class="kv"><div><span>Status</span><b>${chip(el.dataset.s)}</b></div><div><span>What happens next</span><b>We’ll message you when a clinician has reviewed it.</b></div></div></div><div class="dlg-foot"><button class="btn primary lg" data-act="close-modal">Close</button></div>`, { width: 460 });

  /* ---------- Super Admin (holding) ---------- */
  function admin() { const me = App.me();
    return `${head(`Welcome back, ${esc(me.first)}`, 'Platform administration for every LeafEase organisation.')}
    <section class="soon" style="min-height:560px"><div class="soon-bg" aria-hidden="true"></div><span class="soon-icon"><i class="ri-shield-star-line"></i></span><span class="soon-chip"><span class="pulse"></span>Coming soon</span>
      <h2 class="soon-h1">Your Super Admin dashboard is on its way</h2><p class="soon-p">A single view of every organisation on LeafEase — sign-ups, plan usage, system health and support tickets.</p>
      <div class="soon-feats">${[['ri-building-2-line', 'All organisations', 'Clinics, sites and active users'], ['ri-pulse-line', 'System health', 'Uptime, errors and integrations'], ['ri-vip-crown-2-line', 'Plans & billing', 'Subscriptions and renewals']].map(([i, t, d]) => `<div class="soon-feat"><span class="fic"><i class="${i}"></i></span><b>${t}</b><span>${d}</span></div>`).join('')}</div>
      <div class="row g12 wrap" style="justify-content:center"><button class="btn primary lg" data-go="#/inbox"><i class="ri-inbox-line"></i>Open CRM</button><button class="btn outlined lg" data-go="#/hrm/dashboard"><i class="ri-user-search-line"></i>Open Recruitment</button></div></section>`; }
})();
